frappe.ui.form.on('Sales Order', {
	refresh(frm) {
		if (frm.doc.docstatus !== 1) return;

		if (frm.doc.custom_bp_project) {
			frappe.db.get_value('BP Project', frm.doc.custom_bp_project, 'key').then((r) => {
				const key = r.message && r.message.key;
				if (!key) return;
				frm.add_custom_button(__('Open in Batch Projects'), () => {
					window.open(`/workspace/${key}/board`, '_blank');
				});
			});
			return;
		}

		frm.add_custom_button(__('Create Batch Project'), () => {
			frappe.call({
				method: 'batch_projects.api.erp_link.suggest_project_name_for_sales_order',
				args: { sales_order: frm.doc.name },
				callback(sr) {
					const suggested = sr.message || frm.doc.customer_name || frm.doc.customer || '';
					frappe.prompt(
						[{
							fieldname: 'project_name',
							fieldtype: 'Data',
							label: __('Project name'),
							reqd: 1,
							default: suggested,
						}],
						(values) => {
							frappe.call({
								method: 'batch_projects.api.erp_link.create_project_from_sales_order',
								args: { sales_order: frm.doc.name, project_name: values.project_name },
								freeze: true,
								freeze_message: __('Creating Batch Project…'),
								callback(r) {
									if (!r.message) return;
									frm.reload_doc();
									frappe.msgprint({
										title: __('Batch Project created'),
										indicator: 'green',
										message: __('Created {0} with {1} task(s) — {2}', [
											`<b>${frappe.utils.escape_html(r.message.project_name)}</b>`,
											r.message.tasks_created,
											`<a href="/workspace/${r.message.key}/board" target="_blank">${__('open it')}</a>`,
										]),
									});
								},
							});
						},
						__('Name the Batch Project'),
						__('Create')
					);
				},
			});
		});
	},
});

